import * as T from 'three';
// Retain textures, rigs and walking clips; refine the exaggerated child head/eyes in bind space.
export function refinePassengers180(template,record){const child=record.kind137==='child';template.scene.traverse(o=>{if(!o.isMesh)return;for(const m of Array.isArray(o.material)?o.material:[o.material]){if(/hair/i.test(m.name)&&m.transparent){m.alphaTest=.18;m.depthWrite=true;m.alphaToCoverage=true;m.transparent=false;m.side=T.DoubleSide;m.roughness=.82;if(/hair[123]_m/.test(m.name))m.color.set('#40312a');}if(/skin|face|arms|hands/i.test(m.name)){m.metalness=0;m.roughness=Math.min(.78,Math.max(.58,m.roughness));m.envMapIntensity=.38;if(m.map){m.map.anisotropy=Math.max(4,m.map.anisotropy||1);m.map.needsUpdate=true;}}}if(!child||o.userData.natural180)return;const g=o.geometry.clone(),p=g.attributes.position,name=o.name,eye=/CC_Base_Eye|Eye.lash|Eyebrows/i.test(name);for(let i=0;i<p.count;i++){let x=p.getX(i),y=p.getY(i),z=p.getZ(i);if(y>1.39){const blend=T.MathUtils.smoothstep(y,1.39,1.46);if(eye){const cx=x<0?-.053:.050,cy=/Eyebrows/.test(name)?1.584:1.540;x=cx+(x-cx)*.59;y=cy+(y-cy)*.62;z=.04+(z-.04)*.72;}else if(/Body/.test(name)&&z>.025&&y>1.48&&y<1.60&&Math.abs(x)>.025&&Math.abs(x)<.10){const cx=x<0?-.053:.050,w=Math.exp(-(((x-cx)/.047)**2)-(((y-1.540)/.052)**2))*.42;x=cx+(x-cx)*(1-w);y=1.540+(y-1.540)*(1-w);}x*=1-.14*blend;y=1.39+(y-1.39)*(1-.09*blend);z*=1-.12*blend;}p.setXYZ(i,x,y,z);}p.needsUpdate=true;g.computeVertexNormals();g.computeBoundingBox();g.computeBoundingSphere();o.geometry=g;o.userData.natural180=true;});template.natural180=true;}
